mapper.update:
update verification_code
set status = 'REPLACED', updated_at = #{updatedAt}
where purpose = #{purpose} and target = #{target} and status = 'ACTIVE'

update verification_code
set status = 'REPLACED', updated_at = #{updatedAt}
where purpose = #{purpose} and target = #{target} and status in ('ACTIVE', 'SENT', 'PENDING_SEND')

update verification_code
set status = 'REPLACED', updated_at = #{updatedAt}
where purpose = #{purpose}
  and target = #{target}
  and id < #{currentId}
  and status in ('ACTIVE', 'SENT', 'PENDING_SEND')

update verification_code
set status = #{status}, attempt_count = #{attemptCount}, updated_at = #{updatedAt}
where id = #{id}

update verification_code
set status = 'EXPIRED', updated_at = #{updatedAt}
where id = #{id} and status in ('ACTIVE', 'SENT')

update verification_code
set status = 'FROZEN', updated_at = #{updatedAt}
where id = #{id} and status in ('ACTIVE', 'SENT')

update verification_code
set status = #{status}, attempt_count = 0, updated_at = #{updatedAt}
where id = #{id} and status = 'PENDING_SEND'

update verification_code
set status = 'SEND_FAILED', updated_at = #{updatedAt}
where id = #{id}
  and status in ('PENDING_SEND', 'REPLACED')

update verification_code
set status = 'CONSUMED', updated_at = #{updatedAt}
where id = #{id}
  and status in ('ACTIVE', 'SENT')
  and expires_at >= #{updatedAt}
  and attempt_count < max_attempts
